#hud {
  position: fixed; inset: 0; z-index: 10; pointer-events: none; opacity: 0;
  transition: opacity .7s ease .15s;
  text-shadow: 0 1px 3px rgba(0,0,0,.9);
}
body.playing #hud { opacity: 1; }
.hud-top {
  position: absolute; top: calc(18px + var(--safe-t)); left: calc(24px + var(--safe-l)); right: calc(24px + var(--safe-r));
  display: flex; align-items: flex-start; justify-content: space-between; gap: 24px;
}
.objective-card {
  width: 292px; padding: 11px 13px 10px;
  border-left: 1px solid rgba(222,216,200,.34);
  background: linear-gradient(90deg, rgba(6,8,9,.65), rgba(6,8,9,.08));
  backdrop-filter: blur(3px);
}
.eyebrow {
  font-size: 10px; letter-spacing: .24em; color: rgba(222,216,200,.58);
  display: flex; align-items: center; gap: 7px; margin-bottom: 5px; font-weight: 500;
}
.pulse-dot { width: 4px; height: 4px; background: var(--blood-bright); border-radius: 50%; box-shadow: 0 0 8px var(--blood); animation: blink 2.6s infinite; }
.objective-row { display: flex; align-items: flex-start; justify-content: space-between; gap: 10px; }
#objectiveText { font-family: var(--display); font-size: 14px; font-weight: 600; letter-spacing: .08em; line-height: 1.25; }
#objectiveSub { font-size: 11px; color: var(--bone-mute); letter-spacing: .08em; margin-top: 4px; line-height: 1.25; }
.fuse-pips { display: flex; gap: 4px; margin-top: 3px; }
.fuse-pips i { width: 6px; height: 13px; border: 1px solid rgba(222,216,200,.3); background: rgba(0,0,0,.25); transform: skew(-8deg); }
.fuse-pips i.on { background: var(--bone); border-color: var(--bone); box-shadow: 0 0 10px rgba(222,216,200,.45); }
.compass-wrap { position: absolute; left: 50%; top: 2px; transform: translateX(-50%); width: 250px; height: 42px; overflow: hidden; opacity: .64; }
.compass-tape { display: flex; justify-content: space-between; padding: 2px 16px 0; font-family: var(--display); font-size: 9px; letter-spacing: .15em; color: rgba(222,216,200,.66); }
.compass-rule { position: absolute; left: 20px; right: 20px; top: 21px; height: 1px; background: linear-gradient(90deg, transparent, rgba(222,216,200,.23), transparent); }
.compass-notch { position: absolute; left: 50%; top: 16px; width: 1px; height: 11px; background: var(--bone); opacity: .8; }
.rec-wrap { text-align: right; min-width: 100px; }
.rec { display: flex; align-items: center; justify-content: flex-end; gap: 6px; font-size: 10px; letter-spacing: .22em; color: rgba(222,216,200,.7); }
.rec-dot { width: 5px; height: 5px; border-radius: 50%; background: var(--blood-bright); box-shadow: 0 0 8px var(--blood); animation: blink 1.6s infinite; }
.rec-time { font-family: var(--type); font-size: 11px; color: rgba(222,216,200,.4); letter-spacing: .08em; margin-top: 3px; }

.health-panel {
  position: absolute; left: calc(24px + var(--safe-l)); bottom: calc(22px + var(--safe-b)); width: 186px;
  opacity: .76;
}
.vitals-label { display: flex; justify-content: space-between; font-size: 9px; letter-spacing: .2em; color: rgba(222,216,200,.55); margin-bottom: 6px; }
#healthState { color: rgba(181,200,157,.7); letter-spacing: .12em; }
#healthState.danger { color: var(--blood-bright); animation: blink .9s infinite; }
.vitals-bar { position: relative; height: 5px; background: rgba(222,216,200,.1); overflow: hidden; }
#healthFill { height: 100%; width: 100%; background: linear-gradient(90deg, #7b2923, #c1b9a5 60%, #ded8c8); transition: width .35s ease; box-shadow: 0 0 10px rgba(222,216,200,.2); }
.vitals-ticks { position: absolute; inset: 0; background: repeating-linear-gradient(90deg, transparent 0, transparent 18px, rgba(5,6,7,.8) 18px, rgba(5,6,7,.8) 20px); }

.crosshair { position: absolute; left: 50%; top: 50%; width: 34px; height: 34px; transform: translate(-50%,-50%); opacity: .78; transition: transform .15s, opacity .2s; }
.crosshair i { position: absolute; background: rgba(225,220,206,.72); box-shadow: 0 0 3px rgba(0,0,0,.8); transition: opacity .15s; }
.crosshair .ch-t { left: 16px; top: 2px; width: 1px; height: 8px; }
.crosshair .ch-b { left: 16px; bottom: 2px; width: 1px; height: 8px; }
.crosshair .ch-l { left: 2px; top: 16px; width: 8px; height: 1px; }
.crosshair .ch-r { right: 2px; top: 16px; width: 8px; height: 1px; }
.crosshair b { position: absolute; left: 16px; top: 16px; width: 1px; height: 1px; background: rgba(225,220,206,.8); }
.crosshair.aim { transform: translate(-50%,-50%) scale(.72); opacity: 1; }
.crosshair.enemy i, .crosshair.enemy b { background: #c25648; }
.crosshair.hidden { opacity: 0; }
.hitmarker { position: absolute; left: 50%; top: 50%; width: 32px; height: 32px; transform: translate(-50%,-50%) rotate(45deg); opacity: 0; }
.hitmarker i { position: absolute; background: #e6dfce; box-shadow: 0 0 5px rgba(230,223,206,.7); }
.hitmarker i:nth-child(1) { width: 1px; height: 9px; left: 0; top: 0; }
.hitmarker i:nth-child(2) { width: 1px; height: 9px; right: 0; top: 0; }
.hitmarker i:nth-child(3) { width: 1px; height: 9px; left: 0; bottom: 0; }
.hitmarker i:nth-child(4) { width: 1px; height: 9px; right: 0; bottom: 0; }
.hitmarker.show { animation: hit .26s ease-out; }

.weapon-panel {
  position: absolute; right: calc(26px + var(--safe-r)); bottom: calc(25px + var(--safe-b));
  text-align: right; padding-right: 11px; border-right: 1px solid rgba(222,216,200,.3);
  opacity: .85;
}
.weapon-name { font-size: 9px; letter-spacing: .19em; color: rgba(222,216,200,.48); }
.weapon-name span { color: rgba(222,216,200,.28); }
.ammo-row { display: flex; align-items: baseline; justify-content: flex-end; gap: 4px; margin-top: 1px; font-family: var(--display); }
#ammoMag { font-size: 32px; font-weight: 600; line-height: 1; letter-spacing: .02em; }
.slash { color: rgba(222,216,200,.32); font-family: var(--sans); font-size: 17px; }
#ammoReserve { font-size: 16px; color: rgba(222,216,200,.55); }
.reload-hint { font-size: 9px; letter-spacing: .17em; color: rgba(222,216,200,.33); margin-top: 4px; }
.reload-hint.active { color: var(--blood-bright); animation: blink .7s infinite; }

.interact-prompt {
  position: absolute; left: 50%; bottom: 19%; transform: translateX(-50%) translateY(6px);
  display: flex; align-items: center; gap: 9px; padding: 8px 14px 8px 8px;
  background: rgba(5,7,8,.62); border: 1px solid rgba(222,216,200,.18);
  backdrop-filter: blur(6px); opacity: 0; transition: opacity .18s, transform .18s; white-space: nowrap;
  font-size: 11px; letter-spacing: .16em;
}
.interact-prompt.show { opacity: 1; transform: translateX(-50%) translateY(0); }
.prompt-key { display: inline-grid; place-items: center; min-width: 24px; height: 24px; border: 1px solid rgba(222,216,200,.45); font-family: var(--sans); font-size: 11px; letter-spacing: .02em; color: var(--bone); background: rgba(222,216,200,.06); }
.subtitle {
  position: absolute; left: 50%; bottom: 9.5%; transform: translateX(-50%); width: min(660px, 76vw); text-align: center;
  font-family: var(--type); font-size: 14px; line-height: 1.55; color: rgba(235,229,213,.82);
  text-shadow: 0 2px 10px #000, 0 0 2px #000; opacity: 0; transition: opacity .5s;
}
.subtitle.show { opacity: 1; }
.subtitle em { color: var(--bone-mute); font-style: normal; font-size: 11px; letter-spacing: .1em; display: block; margin-top: 5px; font-family: var(--sans); }
.toast {
  position: absolute; left: 50%; top: 16%; transform: translateX(-50%) translateY(6px);
  text-align: center; font-size: 10px; letter-spacing: .26em; color: rgba(222,216,200,.75);
  opacity: 0; transition: opacity .3s, transform .3s; white-space: nowrap;
}
.toast.show { opacity: 1; transform: translateX(-50%) translateY(0); }
.toast b { font-family: var(--display); display: block; font-size: 17px; letter-spacing: .17em; margin-bottom: 3px; color: var(--bone); }
.objective-arrow {
  position: absolute; left: 50%; top: 19%; width: 0; height: 0; border-left: 4px solid transparent; border-right: 4px solid transparent; border-bottom: 9px solid rgba(222,216,200,.7);
  opacity: 0; transform-origin: 50% 55px; transition: opacity .2s;
}
.objective-arrow.show { opacity: .65; }
.desktop-hint {
  position: absolute; left: 50%; bottom: calc(23px + var(--safe-b)); transform: translateX(-50%);
  display: flex; gap: 13px; font-size: 8px; letter-spacing: .14em; color: rgba(222,216,200,.32);
  opacity: 0; transition: opacity 1s; white-space: nowrap;
}
.desktop-hint.show { opacity: 1; }
.desktop-hint b { color: rgba(222,216,200,.58); font-weight: 500; }
body.touch .desktop-hint { display: none; }

/* ---------------- TOUCH ---------------- */
.touch-ui { display: none; }
body.touch .touch-ui { display: block; }
.stick {
  position: absolute; left: calc(25px + var(--safe-l)); bottom: calc(33px + var(--safe-b));
  width: 116px; height: 116px; border-radius: 50%;
  background: radial-gradient(circle at 50% 50%, rgba(222,216,200,.025), transparent 70%);
  pointer-events: auto; opacity: .72;
}
.stick-ring { position: absolute; inset: 9px; border: 1px solid rgba(222,216,200,.22); border-radius: 50%; }
.stick-ring::before, .stick-ring::after { content: ''; position: absolute; background: rgba(222,216,200,.18); }
.stick-ring::before { left: 50%; top: 0; width: 1px; height: 11px; }
.stick-ring::after { left: 0; top: 50%; width: 11px; height: 1px; }
.stick-knob {
  position: absolute; left: 50%; top: 50%; width: 43px; height: 43px; margin: -21.5px 0 0 -21.5px;
  border: 1px solid rgba(222,216,200,.45); border-radius: 50%; background: rgba(12,15,15,.48);
  box-shadow: inset 0 0 18px rgba(0,0,0,.5), 0 0 14px rgba(0,0,0,.3);
}
.touch-brand { position: absolute; left: calc(31px + var(--safe-l)); bottom: calc(156px + var(--safe-b)); font-family: var(--display); font-size: 8px; letter-spacing: .28em; color: rgba(222,216,200,.28); }

.round-btn {
  position: absolute; pointer-events: auto; display: grid; place-items: center;
  border-radius: 50%; color: rgba(230,224,209,.82);
  background: radial-gradient(circle at 35% 30%, rgba(222,216,200,.1), rgba(8,11,12,.38) 62%);
  border: 1px solid rgba(222,216,200,.25); backdrop-filter: blur(4px);
  box-shadow: 0 4px 18px rgba(0,0,0,.35), inset 0 0 20px rgba(0,0,0,.22);
  transition: transform .09s, background .15s, border-color .15s;
}
.round-btn:active, .round-btn.pressed { transform: scale(.94); background: rgba(222,216,200,.16); border-color: rgba(222,216,200,.5); }
.round-btn .btn-label { font-size: 8px; letter-spacing: .2em; color: rgba(222,216,200,.48); margin-top: 2px; }
.round-btn .btn-icon { font-size: 19px; line-height: 1; color: rgba(222,216,200,.8); }
.fire-btn { right: calc(24px + var(--safe-r)); bottom: calc(82px + var(--safe-b)); width: 84px; height: 84px; border-color: rgba(173,95,80,.4); }
.fire-btn .fire-inner { width: 53px; height: 53px; border-radius: 50%; border: 1px solid rgba(199,86,66,.58); background: radial-gradient(circle at 38% 33%, rgba(198,73,57,.32), rgba(80,22,17,.22) 60%, transparent); box-shadow: inset 0 0 13px rgba(140,30,20,.28), 0 0 16px rgba(130,26,19,.14); }
.fire-btn .btn-label { position: absolute; bottom: 10px; }
.fire-btn:active .fire-inner { background: rgba(198,73,57,.5); }
.aim-btn { right: calc(116px + var(--safe-r)); bottom: calc(184px + var(--safe-b)); width: 56px; height: 56px; }
.reload-btn { right: calc(30px + var(--safe-r)); bottom: calc(180px + var(--safe-b)); width: 43px; height: 43px; }
.light-btn { right: calc(115px + var(--safe-r)); bottom: calc(73px + var(--safe-b)); width: 46px; height: 46px; }
.light-btn.off .btn-icon { opacity: .35; }
.interact-btn { right: calc(99px + var(--safe-r)); bottom: calc(265px + var(--safe-b)); width: 58px; height: 58px; opacity: 0; transform: scale(.88); transition: opacity .2s, transform .2s; }
.interact-btn.show { opacity: 1; transform: scale(1); }
.interact-btn .prompt-key { border: 0; min-width: auto; height: auto; background: none; font-family: var(--display); font-size: 20px; }

/* ---------------- MENU ---------------- */
.menu-screen {
  overflow: hidden; background:
    linear-gradient(90deg, rgba(4,6,7,.93) 0%, rgba(4,6,7,.72) 37%, rgba(4,6,7,.16) 70%, rgba(4,6,7,.56) 100%),
    radial-gradient(ellipse at 68% 45%, transparent 15%, rgba(2,4,4,.42) 70%);
}
.menu-screen::after {
  content: ''; position: absolute; inset: 0; pointer-events: none;
  background: linear-gradient(to bottom, rgba(0,0,0,.55), transparent 18%, transparent 75%, rgba(0,0,0,.65)),
    radial-gradient(ellipse at 50% 48%, transparent 40%, rgba(0,0,0,.55) 100%);
}
.menu-grain, .modal-noise, .end-grain {
  position: absolute; inset: -50%; pointer-events: none; opacity: .11;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 220 220' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.92' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.55'/%3E%3C/svg%3E");
  animation: grainShift .35s steps(2) infinite;
  mix-blend-mode: overlay;
}
.menu-top {
  position: absolute; z-index: 3; left: calc(42px + var(--safe-l)); right: calc(42px + var(--safe-r)); top: calc(30px + var(--safe-t));
  display: flex; justify-content: space-between; align-items: center;
  font-size: 9px; letter-spacing: .2em; color: rgba(222,216,200,.43);
}
.menu-brand { display: flex; align-items: center; gap: 9px; }
.brand-mark { display: inline-grid; place-items: center; width: 18px; height: 18px; border: 1px solid rgba(222,216,200,.3); font-size: 11px; color: rgba(222,216,200,.65); }
.menu-brand em { font-style: normal; color: rgba(222,216,200,.2); margin-left: 4px; }
.menu-status { display: flex; align-items: center; gap: 8px; }
.status-dot { width: 4px; height: 4px; background: var(--blood-bright); border-radius: 50%; animation: blink 2s infinite; }
.menu-hero { position: absolute; z-index: 4; left: calc(7.2vw + var(--safe-l)); top: 26%; width: min(760px, 66vw); }
.menu-kicker { display: flex; align-items: center; gap: 12px; font-size: 9px; letter-spacing: .28em; color: rgba(222,216,200,.48); margin-bottom: 2vh; }
.menu-kicker span { width: 22px; height: 1px; background: rgba(222,216,200,.27); }
.menu-hero h1 {
  margin: 0; font-family: var(--display); font-size: clamp(70px, 8.8vw, 142px); font-weight: 700;
  line-height: .86; letter-spacing: .015em; color: #e3dccb;
  text-shadow: 0 5px 40px rgba(0,0,0,.75), 0 0 90px rgba(0,0,0,.35);
  animation: titleBreathe 8s ease-in-out infinite;
}
.menu-hero h1 span { color: #b8b19f; }
.menu-rule { display: flex; align-items: center; gap: 16px; margin: 2.7vh 0 2.2vh; width: min(500px, 80%); }
.menu-rule i { flex: 1; height: 1px; background: linear-gradient(90deg, transparent, rgba(222,216,200,.22)); }
.menu-rule i:last-child { background: linear-gradient(90deg, rgba(222,216,200,.22), transparent); }
.menu-rule b { font-size: 10px; font-weight: 400; letter-spacing: .38em; color: rgba(222,216,200,.53); white-space: nowrap; }
.menu-copy { font-family: var(--type); font-size: 12px; line-height: 1.8; color: rgba(222,216,200,.48); letter-spacing: .03em; margin: 0 0 3.4vh; }
.start-btn {
  display: flex; align-items: center; gap: 15px; width: 214px; height: 54px; padding: 0 20px;
  background: rgba(222,216,200,.93); color: #0b0d0d; border: 1px solid transparent;
  font-size: 15px; letter-spacing: .28em; font-weight: 600; text-align: left;
  box-shadow: 0 0 0 rgba(222,216,200,0); transition: background .2s, box-shadow .25s, width .25s;
}
.start-btn::after { content: ''; width: 7px; height: 7px; border-top: 1px solid #0b0d0d; border-right: 1px solid #0b0d0d; transform: rotate(45deg); margin-left: auto; }
.start-btn:hover { background: #f0ead9; width: 228px; box-shadow: 0 0 34px rgba(222,216,200,.16); }
.start-btn:active { background: #c9c2b0; }
.start-arrow { font-size: 11px; opacity: .65; }
.menu-foot { display: flex; align-items: center; gap: 11px; margin-top: 2.8vh; font-size: 8px; letter-spacing: .17em; color: rgba(222,216,200,.3); }
.menu-sep { color: rgba(222,216,200,.14); }
.text-btn { font-size: 8px; letter-spacing: .17em; color: rgba(222,216,200,.42); border-bottom: 1px solid rgba(222,216,200,.17); padding-bottom: 2px; }
.text-btn:hover { color: var(--bone); }
.case-file {
  position: absolute; z-index: 4; right: calc(5.4vw + var(--safe-r)); top: 24%; width: 250px;
  border: 1px solid rgba(222,216,200,.12); background: rgba(8,11,12,.38);
  padding: 14px; backdrop-filter: blur(2px); transform: rotate(.7deg);
  box-shadow: 12px 16px 55px rgba(0,0,0,.28);
}
.case-head { display: flex; justify-content: space-between; align-items: baseline; font-size: 8px; letter-spacing: .22em; color: rgba(222,216,200,.45); border-bottom: 1px solid rgba(222,216,200,.12); padding-bottom: 8px; }
.case-head b { font-family: var(--type); font-size: 11px; font-weight: 400; color: rgba(222,216,200,.65); letter-spacing: .04em; }
.case-photo { position: relative; height: 132px; margin: 13px 0 12px; overflow: hidden; background: radial-gradient(ellipse at 47% 32%, #35352d, #171a17 52%, #080a09 100%); filter: sepia(.18) contrast(1.12); }
.case-photo::before { content: ''; position: absolute; inset: 0; background: repeating-linear-gradient(0deg, transparent 0, transparent 3px, rgba(0,0,0,.14) 4px); }
.photo-figure { position: absolute; left: 50%; bottom: 0; width: 57px; height: 108px; transform: translateX(-50%); background: linear-gradient(90deg, #0e1210, #272b24 45%, #111512); clip-path: polygon(36% 0, 62% 0, 69% 17%, 64% 29%, 74% 45%, 81% 100%, 18% 100%, 25% 45%, 35% 29%, 29% 17%); opacity: .9; }
.photo-figure::before { content: ''; position: absolute; left: 50%; top: 2px; width: 22px; height: 28px; transform: translateX(-50%); border-radius: 48% 48% 43% 45%; background: #5d5b4f; box-shadow: inset 0 0 8px #141713; }
.photo-figure::after { content: ''; position: absolute; left: 44%; top: 14px; width: 1px; height: 2px; background: #c9b36f; box-shadow: 5px 0 0 #c9b36f, 0 0 4px #d8be72; }
.photo-scratches { position: absolute; inset: 0; background: linear-gradient(76deg, transparent 27%, rgba(220,210,190,.16) 27.2%, transparent 27.5%), linear-gradient(104deg, transparent 64%, rgba(220,210,190,.1) 64.2%, transparent 64.4%); }
.case-file dl { margin: 0; display: grid; gap: 6px; }
.case-file dl div { display: flex; justify-content: space-between; font-size: 8px; letter-spacing: .1em; gap: 8px; }
.case-file dt { color: rgba(222,216,200,.27); }
.case-file dd { margin: 0; color: rgba(222,216,200,.56); text-align: right; }
.case-file dd.red { color: #b65349; letter-spacing: .2em; }
.case-stamp {
  margin-top: 15px; padding: 7px; border: 2px solid rgba(146,48,40,.4); transform: rotate(-4deg);
  font-family: var(--type); font-size: 10px; line-height: 1.1; letter-spacing: .13em; text-align: center; color: rgba(166,60,51,.47); opacity: .85;
}
.menu-bottom { position: absolute; z-index: 4; left: calc(42px + var(--safe-l)); right: calc(42px + var(--safe-r)); bottom: calc(25px + var(--safe-b)); display: flex; justify-content: space-between; font-size: 8px; letter-spacing: .17em; color: rgba(222,216,200,.21); }
.menu-screen.leave { animation: menuLeave .9s ease forwards; pointer-events: none; }
.menu-screen.leave .menu-hero { animation: heroLeave .7s ease forwards; }
.menu-screen.leave .case-file, .menu-screen.leave .menu-top, .menu-screen.leave .menu-bottom { opacity: 0; transition: opacity .4s; }

/* ---------------- LOADING ---------------- */
.loading-screen { z-index: 60; background: #050607; display: grid; place-items: center; transition: opacity .8s; }
.loading-screen.leave { opacity: 0; pointer-events: none; }
.load-inner { width: min(310px, 74vw); text-align: center; }
.load-mark { display: inline-grid; place-items: center; width: 34px; height: 34px; border: 1px solid rgba(222,216,200,.22); color: rgba(222,216,200,.7); font-size: 21px; margin-bottom: 18px; }
.load-title { font-family: var(--display); font-size: 26px; font-weight: 600; letter-spacing: .27em; color: var(--bone); margin-bottom: 26px; }
.load-bar { height: 1px; background: rgba(222,216,200,.12); overflow: hidden; }
.load-bar i { display: block; height: 100%; width: 0%; background: var(--bone); transition: width .5s; box-shadow: 0 0 8px rgba(222,216,200,.6); }
.load-text { margin-top: 12px; font-size: 8px; letter-spacing: .24em; color: rgba(222,216,200,.32); }

/* ---------------- MODALS ---------------- */
.modal-screen { z-index: 40; display: grid; place-items: center; background: rgba(3,5,5,.75); backdrop-filter: blur(7px); }
.pause-inner { position: relative; z-index: 2; width: min(390px, 84vw); text-align: center; }
.modal-kicker { font-size: 8px; letter-spacing: .34em; color: rgba(222,216,200,.34); margin-bottom: 12px; }
.modal-kicker.red { color: #a94539; }
.pause-inner h2, .end-inner h2 { font-family: var(--display); font-weight: 600; margin: 0; letter-spacing: .12em; }
.pause-inner h2 { font-size: 56px; color: var(--bone); }
.pause-inner p { font-family: var(--type); font-size: 12px; color: rgba(222,216,200,.4); margin: 10px 0 30px; }
.modal-actions { display: grid; gap: 8px; }
.panel-btn {
  min-height: 47px; border: 1px solid rgba(222,216,200,.16); color: rgba(222,216,200,.65);
  font-size: 12px; letter-spacing: .22em; background: rgba(222,216,200,.02); transition: .18s; padding: 0 18px;
}
.panel-btn:hover { border-color: rgba(222,216,200,.38); color: var(--bone); background: rgba(222,216,200,.05); }
.panel-btn.primary { background: rgba(222,216,200,.9); color: #0a0c0c; border-color: transparent; font-weight: 600; }
.panel-btn.primary:hover { background: #f0e9d8; }
